		//Paso 1: Definir e inicializar el arreglo
		int[] values = {5, 8, 4, 78, 95, 12, 1, 0, 6, 35, 46};
		//Paso 2: Establecer el primer valor como el mayor hasta ahora.
		int maxValue = values[0];
		//Paso 3: Iterar por los valores restantes del arreglo y determinar cual es el valor maximo
		for (int i = 1; i < values.length; i++) {
			//Paso 3.1: Determinar si el elemento en el indice i es el mayor hasta ahora
			if (values[i] > maxValue) {
				maxValue = values[i];
			}
		}
		//Paso 4: Imprimir el valor maximo del arreglo
		System.out.println("Valor maximo: " + maxValue);
	}
}

